 (1020, '数学', '三年级', '填空', 1, '{"stem": "一个角有( )个顶点。", "options": null}', '1', '角是由一个顶点和两条直边组成的，所以一个角有 1 个顶点。', 'seed', '["practice", "VG-G3-3-1"]', NULL, 0),
 (1020, '数学', '三年级', '判断', 1, '{"stem": "角有一个顶点和两条边。（ ）", "options": null}', '对', '角就是由一个顶点和两条直边组成的图形。', 'seed', '["practice", "VG-G3-3-1"]', NULL, 0),
 (1020, '数学', '三年级', '判断', 2, '{"stem": "角的两条边越长，这个角就越大。（ ）", "options": null}', '错', '角的大小与两条边张开的大小有关，与边的长短无关，边再长角也不变大。', 'seed', '["practice", "VG-G3-3-1"]', NULL, 0),
 (1020, '数学', '三年级', '选择', 2, '{"stem": "角的大小与（ ）有关。", "options": ["① 边的长短", "② 两边张开的大小", "③ 顶点的位置"]}', '②', '角的大小只与两边张开的大小（张口）有关，张口越大角越大。', 'seed', '["practice", "VG-G3-3-1"]', NULL, 0),
 (1020, '数学', '三年级', '判断', 2, '{"stem": "用放大镜看一个角，角会变大。（ ）", "options": null}', '错', '放大镜只是把角整体放大，两边张开的程度没变，所以角的大小不变。', 'seed', '["practice", "VG-G3-3-1"]', NULL, 0),
 (1021, '数学', '三年级', '选择', 2, '{"stem": "三角尺上最大的角是（ ）。", "options": ["① 锐角", "② 直角", "③ 钝角"]}', '②', '每把三角尺上都有 1 个直角和 2 个锐角，最大的角是直角。', 'seed', '["diagnostic", "VG-G3-3-2"]', NULL, 0),
 (1021, '数学', '三年级', '判断', 1, '{"stem": "所有的直角都一样大。（ ）", "options": null}', '对', '直角都是 90°，无论画在哪里、画多大，直角都一样大。', 'seed', '["practice", "VG-G3-3-2"]', NULL, 0),
 (1021, '数学', '三年级', '判断', 2, '{"stem": "锐角一定比钝角大。（ ）", "options": null}', '错', '锐角比直角小，钝角比直角大，所以锐角一定比钝角小。', 'seed', '["practice", "VG-G3-3-2"]', NULL, 0),
 (1021, '数学', '三年级', '选择', 2, '{"stem": "钟面上 3 时整，时针和分针组成的角是（ ）。", "options": ["① 锐角", "② 直角", "③ 钝角"]}', '②', '3 时整时针指向 3、分针指向 12，两针正好互相垂直，组成直角。', 'seed', '["practice", "VG-G3-3-2"]', NULL, 0),
 (1021, '数学', '三年级', '填空', 1, '{"stem": "一把三角尺上有( )个直角。", "options": null}', '1', '每把三角尺上只有 1 个直角，另外 2 个都是锐角。', 'seed', '["practice", "VG-G3-3-2"]', NULL, 0),
 (1022, '数学', '三年级', '判断', 2, '{"stem": "由 4 条线段组成的图形就是四边形。（ ）", "options": null}', '错', '四边形必须是由 4 条线段首尾相接围成的封闭图形，只是画出 4 条线段不算。', 'seed', '["practice", "VG-G3-3-3"]', NULL, 0),
 (1022, '数学', '三年级', '填空', 1, '{"stem": "长方形和正方形都是( )边形。", "options": null}', '四', '长方形和正方形都有 4 条边，都是四边形。', 'seed', '["practice", "VG-G3-3-3"]', NULL, 0),
 (1022, '数学', '三年级', '判断', 1, '{"stem": "五边形有 5 条边、5 个角。（ ）", "options": null}', '对', '几边形就有几条边、几个角，五边形有 5 条边、5 个角。', 'seed', '["practice", "VG-G3-3-3"]', NULL, 0),
 (1022, '数学', '三年级', '选择', 2, '{"stem": "下面图形中不是四边形的是（ ）。", "options": ["① 正方形", "② 长方形", "③ 三角形"]}', '③', '正方形和长方形都有 4 条边是四边形，三角形只有 3 条边不是四边形。', 'seed', '["practice", "VG-G3-3-3"]', NULL, 0),
 (1022, '数学', '三年级', '判断', 1, '{"stem": "三角形有 3 条边、3 个角。（ ）", "options": null}', '对', '三角形由 3 条线段围成，有 3 条边、3 个角。', 'seed', '["practice", "VG-G3-3-3"]', NULL, 0),
 (1023, '数学', '三年级', '选择', 1, '{"stem": "长方形有（ ）个直角。", "options": ["① 2 个", "② 3 个", "③ 4 个"]}', '③', '长方形有 4 条边、4 个角，4 个角都是直角。', 'seed', '["practice", "VG-G3-3-4"]', NULL, 0),
 (1023, '数学', '三年级', '判断', 1, '{"stem": "长方形对边相等，四个角都是直角。（ ）", "options": null}', '对', '长方形对边相等，四个角都是直角，这是长方形的特征。', 'seed', '["practice", "VG-G3-3-4"]', NULL, 0),
 (1023, '数学', '三年级', '判断', 2, '{"stem": "正方形是特殊的长方形。（ ）", "options": null}', '对', '正方形和长方形都有 4 个直角，正方形还要求 4 条边都相等，所以正方形是特殊的长方形。', 'seed', '["practice", "VG-G3-3-4"]', NULL, 0),
 (1023, '数学', '三年级', '填空', 1, '{"stem": "正方形的( )条边都相等。", "options": null}', '4', '正方形的 4 条边都相等，4 个角都是直角。', 'seed', '["practice", "VG-G3-3-4"]', NULL, 0),
 (1023, '数学', '三年级', '判断', 2, '{"stem": "四边形不是长方形就是正方形。（ ）", "options": null}', '错', '四边形还包括梯形、平行四边形等，长方形和正方形只是其中两种。', 'seed', '["practice", "VG-G3-3-4"]', NULL, 0),
 (1024, '数学', '三年级', '填空', 2, '{"stem": "三个角都是锐角的三角形叫( )三角形。", "options": null}', '锐角', '三个角都是锐角的三角形叫锐角三角形。', 'seed', '["practice", "VG-G3-3-5"]', NULL, 0),
 (1024, '数学', '三年级', '判断', 1, '{"stem": "有一个角是直角的三角形是直角三角形。（ ）", "options": null}', '对', '只要三角形中有一个角是直角，它就是直角三角形。', 'seed', '["practice", "VG-G3-3-5"]', NULL, 0),
 (1024, '数学', '三年级', '判断', 2, '{"stem": "一个三角形能有 2 个直角。（ ）", "options": null}', '错', '2 个直角合起来已经是一个平角，第三个角就无法存在了，三角形最多只有 1 个直角。', 'seed', '["practice", "VG-G3-3-5"]', NULL, 0),
 (1024, '数学', '三年级', '选择', 2, '{"stem": "一个三角形中有一个角是钝角，这个三角形是（ ）。", "options": ["① 锐角三角形", "② 直角三角形", "③ 钝角三角形"]}', '③', '有一个角是钝角的三角形叫钝角三角形。', 'seed', '["practice", "VG-G3-3-5"]', NULL, 0),
 (1024, '数学', '三年级', '判断', 3, '{"stem": "一个三角形至少有 2 个锐角。（ ）", "options": null}', '对', '直角三角形和钝角三角形除了直角或钝角外，另外两个角都必须是锐角，所以三角形至少有 2 个锐角。', 'seed', '["practice", "VG-G3-3-5"]', NULL, 0),
 (1039, '数学', '三年级', '填空', 1, '{"stem": "1 厘米 = ( )毫米。", "options": null}', '10', '1 厘米里有 10 个 1 毫米，所以 1 厘米 = 10 毫米。', 'seed', '["practice", "VG-G3-6-1"]', NULL, 0),
 (1039, '数学', '三年级', '填空', 1, '{"stem": "1 分米 = ( )厘米。", "options": null}', '10', '1 分米里有 10 个 1 厘米，所以 1 分米 = 10 厘米。', 'seed', '["practice", "VG-G3-6-1"]', NULL, 0),
 (1039, '数学', '三年级', '判断', 2, '{"stem": "1 米 = 100 毫米。（ ）", "options": null}', '错', '1 米 = 100 厘米 = 1000 毫米，不是 100 毫米。', 'seed', '["practice", "VG-G3-6-1"]', NULL, 0),
 (1039, '数学', '三年级', '填空', 2, '{"stem": "3 分米 = ( )毫米。", "options": null}', '300', '3 分米 = 30 厘米 = 300 毫米。', 'seed', '["practice", "VG-G3-6-1"]', NULL, 0),
 (1039, '数学', '三年级', '判断', 2, '{"stem": "测量课本的厚度，用毫米作单位比较合适。（ ）", "options": null}', '对', '课本厚度只有几毫米到几厘米，用毫米作单位能量得更准确。', 'seed', '["practice", "VG-G3-6-1"]', NULL, 0),
 (1040, '数学', '三年级', '填空', 2, '{"stem": "3 米 5 厘米 = ( )厘米。", "options": null}', '305', '3 米 = 300 厘米，300+5=305（厘米）。', 'seed', '["practice", "VG-G3-6-2"]', NULL, 0),
 (1040, '数学', '三年级', '填空', 2, '{"stem": "1 米 20 厘米 = ( )厘米。", "options": null}', '120', '1 米 = 100 厘米，100+20=120（厘米）。', 'seed', '["practice", "VG-G3-6-2"]', NULL, 0),
 (1040, '数学', '三年级', '填空', 3, '{"stem": "2 分米 6 毫米 = ( )毫米。", "options": null}', '206', '2 分米 = 200 毫米，200+6=206（毫米）。', 'seed', '["practice", "VG-G3-6-2"]', NULL, 0),
 (1040, '数学', '三年级', '选择', 2, '{"stem": "105 厘米 = ( )。", "options": ["① 1 米 5 厘米", "② 10 米 5 厘米", "③ 1 米 50 厘米"]}', '①', '105 厘米 = 100 厘米 + 5 厘米 = 1 米 5 厘米。', 'seed', '["practice", "VG-G3-6-2"]', NULL, 0),
 (1040, '数学', '三年级', '判断', 2, '{"stem": "3 米 5 厘米 = 35 厘米。（ ）", "options": null}', '错', '3 米 = 300 厘米，3 米 5 厘米 = 305 厘米，漏看“米”直接写 35 就错了。', 'seed', '["practice", "VG-G3-6-2"]', NULL, 0),
 (1041, '数学', '三年级', '填空', 1, '{"stem": "封闭图形( )的长度，就是它的周长。", "options": null}', '一周', '封闭图形一周的长度就是它的周长。', 'seed', '["practice", "VG-G3-6-3"]', NULL, 0),
 (1041, '数学', '三年级', '判断', 1, '{"stem": "长方形一周的长度就是长方形的周长。（ ）", "options": null}', '对', '围成长方形一周的长度就是长方形的周长。', 'seed', '["practice", "VG-G3-6-3"]', NULL, 0),
 (1041, '数学', '三年级', '判断', 2, '{"stem": "只有长方形和正方形才有周长。（ ）", "options": null}', '错', '三角形、圆、五边形等所有封闭图形都有周长。', 'seed', '["practice", "VG-G3-6-3"]', NULL, 0),
 (1041, '数学', '三年级', '判断', 2, '{"stem": "三角形的周长等于它三条边的长度和。（ ）", "options": null}', '对', '围成三角形一周的长度就是三条边相加，所以周长等于三条边的和。', 'seed', '["practice", "VG-G3-6-3"]', NULL, 0),
 (1041, '数学', '三年级', '选择', 2, '{"stem": "下面图形中，（ ）没有周长。", "options": ["① 三角形", "② 圆形", "③ 角"]}', '③', '角不是封闭图形，围不成一周，所以角没有周长；三角形和圆都是封闭图形，有周长。', 'seed', '["practice", "VG-G3-6-3"]', NULL, 0),
 (1042, '数学', '三年级', '应用题', 2, '{"stem": "一个长方形长 8 厘米、宽 5 厘米，它的周长是多少厘米？", "options": null}', '26厘米', '长方形周长 =（长+宽）×2 =（8+5）×2 = 26（厘米）。', 'seed', '["diagnostic", "VG-G3-6-4"]', NULL, 0),
 (1042, '数学', '三年级', '应用题', 2, '{"stem": "长方形花坛长 9 米、宽 6 米，绕花坛走一圈是多少米？", "options": null}', '30米', '绕一圈就是求周长：（9+6）×2 = 30（米）。', 'seed', '["practice", "VG-G3-6-4"]', NULL, 0),
 (1042, '数学', '三年级', '应用题', 3, '{"stem": "一个长方形周长是 24 厘米，长是 8 厘米，宽是多少厘米？", "options": null}', '4厘米', '先求长加宽：24÷2=12（厘米），再求宽：12-8=4（厘米）。注意周长要先除以 2。', 'seed', '["practice", "VG-G3-6-4"]', NULL, 0),
 (1042, '数学', '三年级', '应用题', 3, '{"stem": "一块长方形菜地长 12 米、宽 8 米，一面靠墙（长边靠墙），其余三边围篱笆，至少需要篱笆多少米？", "options": null}', '28米', '长边靠墙不用围，篱笆 = 两条宽 + 一条长 = 8×2+12 = 28（米），不能直接套整个周长公式。', 'seed', '["practice", "VG-G3-6-4"]', NULL, 0),
 (1042, '数学', '三年级', '选择', 3, '{"stem": "用两根同样长的铁丝分别围成一个长方形和一个正方形（都无剩余），它们的周长（ ）。", "options": ["① 长方形长", "② 正方形长", "③ 一样长"]}', '③', '两根铁丝同样长，围成的图形一周的长度都等于铁丝长，所以周长一样长。', 'seed', '["practice", "VG-G3-6-4"]', NULL, 0),
 (1043, '数学', '三年级', '应用题', 2, '{"stem": "正方形边长 6 厘米，周长是多少厘米？", "options": null}', '24厘米', '正方形周长 = 边长×4 = 6×4 = 24（厘米）。', 'seed', '["practice", "VG-G3-6-5"]', NULL, 0),
 (1043, '数学', '三年级', '应用题', 2, '{"stem": "正方形手帕边长 2 分米，四周缝一圈花边，花边长多少分米？", "options": null}', '8分米', '花边长度就是正方形周长：2×4 = 8（分米）。', 'seed', '["practice", "VG-G3-6-5"]', NULL, 0),
 (1043, '数学', '三年级', '应用题', 3, '{"stem": "正方形周长是 36 厘米，它的边长是多少厘米？", "options": null}', '9厘米', '边长 = 周长÷4 = 36÷4 = 9（厘米）。', 'seed', '["practice", "VG-G3-6-5"]', NULL, 0),
 (1043, '数学', '三年级', '判断', 2, '{"stem": "正方形的周长等于边长乘 4。（ ）", "options": null}', '对', '正方形 4 条边都相等，周长就是 4 个边长相加，即边长×4。', 'seed', '["practice", "VG-G3-6-5"]', NULL, 0),
 (1043, '数学', '三年级', '选择', 2, '{"stem": "边长 1 米的正方形，周长是（ ）。", "options": ["① 4 米", "② 40 厘米", "③ 400 毫米"]}', '①', '正方形周长 = 1×4 = 4（米）。', 'seed', '["practice", "VG-G3-6-5"]', NULL, 0),
 (1044, '数学', '三年级', '应用题', 3, '{"stem": "把两个边长 3 厘米的正方形拼成一个长方形，拼成的长方形周长是多少厘米？", "options": null}', '18厘米', '拼成的长方形长 3×2=6 厘米、宽 3 厘米，周长 =（6+3）×2 = 18（厘米）。', 'seed', '["practice", "VG-G3-6-6"]', NULL, 0),
 (1044, '数学', '三年级', '应用题', 3, '{"stem": "一个边长 8 厘米的正方形，剪成两个完全一样的长方形，每个长方形的周长是多少厘米？", "options": null}', '24厘米', '剪开后每个长方形长 8 厘米、宽 8÷2=4 厘米，周长 =（8+4）×2 = 24（厘米）。', 'seed', '["practice", "VG-G3-6-6"]', NULL, 0),
 (1044, '数学', '三年级', '判断', 3, '{"stem": "两个周长 8 厘米的正方形拼成一个长方形，长方形的周长是 16 厘米。（ ）", "options": null}', '错', '拼在一起会重合 2 条边，周长不是 8×2。周长 8 厘米的正方形边长是 2 厘米，拼成长 4 厘米、宽 2 厘米的长方形，周长是（4+2）×2 = 12 厘米。', 'seed', '["practice", "VG-G3-6-6"]', NULL, 0),
 (1044, '数学', '三年级', '选择', 3, '{"stem": "用 4 个边长 1 厘米的小正方形拼成一个大正方形，大正方形的周长是（ ）。", "options": ["① 8 厘米", "② 16 厘米", "③ 4 厘米"]}', '①', '4 个小正方形拼成的大正方形边长是 2 厘米，周长 = 2×4 = 8 厘米。不能把 4 个小正方形周长直接相加。', 'seed', '["practice", "VG-G3-6-6"]', NULL, 0),
 (1044, '数学', '三年级', '应用题', 3, '{"stem": "一个长方形长 12 米、宽 8 米，从中剪下一个最大的正方形，剩下图形的周长是多少米？", "options": null}', '24米', '最大正方形以宽 8 米为边长。剩下长方形长 8 米、宽 12-8=4 米，周长 =（8+4）×2 = 24（米）。', 'seed', '["practice", "VG-G3-6-6"]', NULL, 0);
